export interface LinearWebhookPayload {
  action: 'update';
  type: 'Issue';
  data: {
    id: string;
    state: {
      type: string;
    };
  };
  createdAt: string;
  webhookTimestamp: number;
  comments?: LinearComment[];
  cursor?: string;
}

export interface LinearComment {
  id: string;
  body: string;
  createdAt: string;
  user: {
    id: string;
    name: string;
  };
}

export interface ConnectorConfig {
  discordBotToken: string;
  linearWebhookSecret: string;
  linearApiBaseUrl?: string;
  linearApiToken?: string;
  fetch?: typeof fetch;
  linearFetch?: typeof fetch;
}

export interface HandleResult {
  discordMessageIds: string[];
  commentsFetched: number;
}

async function fetchAllComments(
  issueId: string,
  initialCursor: string | undefined,
  config: ConnectorConfig
): Promise<LinearComment[]> {
  const baseUrl = config.linearApiBaseUrl ?? 'https://api.linear.app';
  const fetchFn = config.linearFetch ?? config.fetch ?? fetch;
  const allComments: LinearComment[] = [];
  let cursor = initialCursor;

  do {
    const url = new URL(`${baseUrl}/issues/${issueId}/comments`);
    if (cursor) {
      url.searchParams.set('cursor', cursor);
    }

    const headers: Record<string, string> = {
      Accept: 'application/json',
    };
    if (config.linearApiToken) {
      headers.Authorization = `Bearer ${config.linearApiToken}`;
    }

    const response = await fetchFn(url.toString(), {
      method: 'GET',
      headers,
    });

    if (!response.ok) {
      throw new Error(`Linear API error: ${response.status} ${response.statusText} for GET ${url.toString()}`);
    }

    const data = (await response.json()) as {
      data: LinearComment[];
      nextCursor: string | null;
    };

    allComments.push(...data.data);
    cursor = data.nextCursor ?? undefined;
  } while (cursor);

  return allComments;
}

function formatDigest(issueId: string, comments: LinearComment[]): string {
  if (comments.length === 0) {
    return `Digest of comments for Linear issue ${issueId}:\n\nNo comments found.`;
  }

  const lines = comments.map((c, i) => `- Comment ${i + 1}: ${c.body}`);
  return `Digest of comments for Linear issue ${issueId}:\n\n${lines.join('\n')}`;
}

function splitMessage(content: string, maxLength = 2000): string[] {
  if (content.length <= maxLength) {
    return [content];
  }

  const chunks: string[] = [];
  let remaining = content;

  while (remaining.length > 0) {
    if (remaining.length <= maxLength) {
      chunks.push(remaining);
      break;
    }

    let splitIndex = remaining.lastIndexOf('\n', maxLength);
    if (splitIndex === -1 || splitIndex < maxLength * 0.5) {
      splitIndex = maxLength;
    }

    chunks.push(remaining.slice(0, splitIndex));
    remaining = remaining.slice(splitIndex).trimStart();
  }

  return chunks;
}

async function postToDiscord(channelId: string, content: string, config: ConnectorConfig): Promise<string> {
  const fetchFn = config.fetch ?? fetch;
  const url = `https://discord.com/api/v9/channels/${channelId}/messages`;

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bot ${config.discordBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  });

  if (!response.ok) {
    throw new Error(`Discord API error: ${response.status} ${response.statusText} for POST ${url}`);
  }

  const data = (await response.json()) as { id: string };
  return data.id;
}

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!config.discordBotToken) {
    throw new Error('Missing required config: discordBotToken');
  }
  if (!config.linearWebhookSecret) {
    throw new Error('Missing required config: linearWebhookSecret');
  }

  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: must be an object');
  }
  if (payload.action !== 'update') {
    throw new Error(`Invalid payload action: expected 'update', got '${payload.action}'`);
  }
  if (payload.type !== 'Issue') {
    throw new Error(`Invalid payload type: expected 'Issue', got '${payload.type}'`);
  }
  if (!payload.data || !payload.data.id) {
    throw new Error('Missing required field: data.id (issueId)');
  }
  if (!payload.data.state || !payload.data.state.type) {
    throw new Error('Missing required field: data.state.type');
  }
  const stateType = payload.data.state.type;
  if (stateType !== 'done' && stateType !== 'canceled') {
    throw new Error(`Issue not closed: state.type is '${stateType}', expected 'done' or 'canceled'`);
  }
  if (typeof payload.webhookTimestamp !== 'number') {
    throw new Error('Missing required field: webhookTimestamp');
  }

  const now = Date.now();
  const timestampDiff = Math.abs(now - payload.webhookTimestamp);
  if (timestampDiff > 60_000) {
    throw new Error(`Webhook timestamp too old or future: ${payload.webhookTimestamp} (diff: ${timestampDiff}ms)`);
  }

  const issueId = payload.data.id;
  const channelId = issueId;

  let comments: LinearComment[];
  if (payload.comments && payload.comments.length > 0) {
    comments = payload.comments;
  } else {
    comments = await fetchAllComments(issueId, payload.cursor, config);
  }

  const digest = formatDigest(issueId, comments);
  const chunks = splitMessage(digest);

  const messageIds: string[] = [];
  for (const chunk of chunks) {
    const messageId = await postToDiscord(channelId, chunk, config);
    messageIds.push(messageId);
  }

  return {
    discordMessageIds: messageIds,
    commentsFetched: comments.length,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, LinearWebhookPayload, ConnectorConfig, HandleResult } from './connector';
import { SOURCE_EXAMPLE, contractFetch, jsonResponse, fakeFetch } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const linearFetch = vi.fn().mockResolvedValue(jsonResponse({ data: [], nextCursor: null }));
    const config: ConnectorConfig = {
      discordBotToken: 'test-bot-token',
      linearWebhookSecret: 'test-secret',
      linearFetch,
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.discordMessageIds.length).toBe(1);
    expect(result.commentsFetched).toBe(0);
  });
});

describe('handle', () => {
  it('happy path: fetches comments via pagination and posts digest to Discord', async () => {
    const issueId = 'issue-123';
    const commentsPage1 = [
      { id: 'c1', body: 'First comment', createdAt: '2024-01-01T10:00:00Z', user: { id: 'u1', name: 'Alice' } },
      { id: 'c2', body: body: body: 'Second comment', createdAt: '2024-01-01T11:00:00Z', user: { id: 'u2', name: 'Bob' } },
    ];
    const commentsPage2 = [
      { id: 'c3', body: 'Third comment', createdAt: '2024-01-01T12:00:00Z', user: { id: 'u3', name: 'Carol' } },
    ];

    const { fetch, calls } = fakeFetch((req) => {
      const url = req.url;
      if (url.includes('/issues/') && url.includes('/comments')) {
        const cursor = new URL(url).searchParams.get('cursor');
        if (!cursor || cursor === 'cursor-1') {
          return jsonResponse({ data: commentsPage1, nextCursor: 'cursor-2' });
        }
        if (cursor === 'cursor-2') {
          return jsonResponse({ data: commentsPage2, nextCursor: null });
        }
        return jsonResponse({ error: 'invalid cursor' }, 400);
      }
      if (url.includes('/channels/') && url.includes('/messages')) {
        return jsonResponse({ id: `msg-${calls.length + 1}` }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: issueId, state: { type: 'done' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now(),
      cursor: 'cursor-1',
    };

    const config: ConnectorConfig = {
      discordBotToken: 'bot-token',
      linearWebhookSecret: 'secret',
      linearApiBaseUrl: 'https://api.linear.app',
      fetch,
      linearFetch: fetch,
    };

    const result = await handle(payload, config);

    expect(result.commentsFetched).toBe(3);
    expect(result.discordMessageIds).toHaveLength(1);
    expect(calls.length).toBe(3);

    expect(calls[0].method).toBe('GET');
    expect(calls[0].url).toContain(`/issues/${issueId}/comments`);
    expect(calls[0].url).toContain('cursor=cursor-1');
    expect(calls[1].method).toBe('GET');
    expect(calls[1].url).toContain('cursor=cursor-2');

    expect(calls[2].method).toBe('POST');
    expect(calls[2].url).toBe(`https://discord.com/api/v9/channels/${issueId}/messages`);
    expect(calls[2].headers.get('authorization')).toBe('Bot bot-token');
    const discordBody = calls[2].json as { content: string };
    expect(discordBody.content).toContain('Digest of comments for Linear issue issue-123');
    expect(discordBody.content).toContain('First comment');
    expect(discordBody.content).toContain('Third comment');
  });

  it('uses comments from payload directly without calling Linear API', async () => {
    const issueId = 'issue-456';
    const comments = [
      { id: 'c1', body: 'Payload comment', createdAt: '2024-01-01T10:00:00Z', user: { id: 'u1', name: 'Alice' } },
    ];

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/channels/')) {
        return jsonResponse({ id: 'msg-1' }, 201);
      }
      return jsonResponse({ error: 'should not call Linear API' }, 500);
    });

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: issueId, state: { type: 'canceled' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now(),
      comments,
    };

    const config: ConnectorConfig = {
      discordBotToken: 'bot-token',
      linearWebhookSecret: 'secret',
      fetch,
      linearFetch: fetch,
    };

    const result = await handle(payload, config);

    expect(result.commentsFetched).toBe(1);
    expect(result.discordMessageIds).toHaveLength(1);
    expect(calls.length).toBe(1);
    expect(calls[0].url).toContain('/channels/');
  });

  it('throws on missing required field data.id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      action: 'update',
      type: 'Issue',
      data: { state: { type: 'done' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now(),
    } as unknown as LinearWebhookPayload;

    const config: ConnectorConfig = {
      discordBotToken: 'bot-token',
      linearWebhookSecret: 'secret',
      fetch,
    };

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: data.id');
  });

  it('throws on non-2xx Discord response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/channels/')) {
        return jsonResponse({ error: 'Unauthorized' }, 401);
      }
      return jsonResponse({ data: [], nextCursor: null });
    });

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'issue-1', state: { type: 'done' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now(),
    };

    const config: ConnectorConfig = {
      discordBotToken: 'bad-token',
      linearWebhookSecret: 'secret',
      fetch,
      linearFetch: fetch,
    };

    await expect(handle(payload, config)).rejects.toThrow('Discord API error: 401 Unauthorized');
    expect(calls.length).toBe(1);
    expect(calls[0].url).toContain('/channels/');
  });

  it('throws on non-2xx Linear API response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/issues/')) {
        return jsonResponse({ error: 'Not Found' }, 404);
      }
      return jsonResponse({}, 200);
    });

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'issue-404', state: { type: 'done' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now(),
    };

    const config: ConnectorConfig = {
      discordBotToken: 'bot-token',
      linearWebhookSecret: 'secret',
      fetch,
      linearFetch: fetch,
    };

    await expect(handle(payload, config)).rejects.toThrow('Linear API error: 404 Not Found');
    expect(calls.length).toBe(1);
    expect(calls[0].url).toContain('/issues/');
  });

  it('throws when webhook timestamp is too old', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'issue-1', state: { type: 'done' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now() - 120_000,
    };

    const config: ConnectorConfig = {
      discordBotToken: 'bot-token',
      linearWebhookSecret: 'secret',
      fetch,
    };

    await expect(handle(payload, config)).rejects.toThrow('Webhook timestamp too old');
  });

  it('splits long digest into multiple Discord messages', async () => {
    const issueId = 'issue-long';
    const manyComments = Array.from({ length: 50 }, (_, i) => ({
      id: `c${i}`,
      body: `Comment ${i} with some text to make it long enough to exceed the limit when combined. `.repeat(5),
      createdAt: '2024-01-01T10:00:00Z',
      user: { id: 'u1', name: 'User' },
    }));

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/issues/')) {
        return jsonResponse({ data: manyComments, nextCursor: null });
      }
      if (req.url.includes('/channels/')) {
        return jsonResponse({ id: `msg-${calls.length + 1}` }, 201);
      }
      return jsonResponse({}, 404);
    });

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: issueId, state: { type: 'done' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now(),
    };

    const config: ConnectorConfig = {
      discordBotToken: 'bot-token',
      linearWebhookSecret: 'secret',
      fetch,
      linearFetch: fetch,
    };

    const result = await handle(payload, config);

    expect(result.discordMessageIds.length).toBeGreaterThan(1);
    expect(calls.filter(c => c.url.includes('/channels/')).length).toBe(result.discordMessageIds.length);
  });

  it('validates action and type', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const basePayload = {
      data: { id: 'issue-1', state: { type: 'done' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now(),
    };

    await expect(handle({ ...basePayload, action: 'create', type: 'Issue' } as unknown as LinearWebhookPayload, { discordBotToken: 't', linearWebhookSecret: 's', fetch })).rejects.toThrow("Invalid payload action: expected 'update'");
    await expect(handle({ ...basePayload, action: 'update', type: 'Project' } as unknown as LinearWebhookPayload, { discordBotToken: 't', linearWebhookSecret: 's', fetch })).rejects.toThrow("Invalid payload type: expected 'Issue'");
  });

  it('validates state type is closed', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'issue-1', state: { type: 'started' } },
      createdAt: '2024-01-01T12:00:00.000Z',
      webhookTimestamp: Date.now(),
    };
    const config: ConnectorConfig = { discordBotToken: 't', linearWebhookSecret: 's', fetch };
    await expect(handle(payload, config)).rejects.toThrow("Issue not closed: state.type is 'started'");
  });
});

# Linear Issue Closed to Discord Digest

This connector receives a Linear `issue.closed` webhook, fetches all comments for the issue via Linear's cursor-paginated API, formats them into a digest, and posts the digest to a Discord channel.

## What it does

1. Receives a Linear webhook payload (validated for `action: update`, `type: Issue`, closed state).
2. Verifies the webhook timestamp is within 60 seconds (replay protection).
3. Extracts the Linear issue ID.
4. Retrieves all comments:
   - If the webhook payload includes `comments`, uses them directly.
   - Otherwise, fetches comments from the Linear API using cursor pagination (`GET /issues/{issueId}/comments?cursor=...`).
5. Formats comments into a digest string: `Digest of comments for Linear issue {issueId}:\n\n- Comment 1: ...\n- Comment 2: ...`
6. Splits the digest into chunks ≤ 2000 characters (Discord limit).
7. Posts each chunk to Discord (`POST https://discord.com/api/v9/channels/{channelId}/messages`) where `channelId` = Linear issue ID.

## Configuration / Environment Variables

| Config Property | Environment Variable | Description |
|-----------------|----------------------|-------------|
| `discordBotToken` | `DISCORD_BOT_TOKEN` | Discord bot token with `Send Messages` permission in the target channel. |
| `linearWebhookSecret` | `LINEAR_WEBHOOK_SECRET` | Secret used to verify `Linear-Signature` header (verified by webhook framework; used here for timestamp check). |
| `linearApiBaseUrl` | `LINEAR_API_BASE_URL` | (Optional) Base URL for Linear API. Default: `https://api.linear.app`. |
| `linearApiToken` | `LINEAR_API_TOKEN` | (Optional) Bearer token for Linear API authentication. |
| `fetch` | — | (Optional) Injected `fetch` implementation for Discord calls. Defaults to global `fetch`. |
| `linearFetch` | — | (Optional) Injected `fetch` for Linear API calls. Defaults to `fetch`. |

## Usage Example

```typescript
import { handle, LinearWebhookPayload, ConnectorConfig } from './connector';

// In your webhook handler (e.g., Express, Fastify, Cloudflare Worker):
app.post('/linear-webhook', async (req, res) => {
  // 1. Verify Linear-Signature header using LINEAR_WEBHOOK_SECRET (omitted here)
  const payload = req.body as LinearWebhookPayload;

  const config: ConnectorConfig = {
    discordBotToken: process.env.DISCORD_BOT_TOKEN!,
    linearWebhookSecret: process.env.LINEAR_WEBHOOK_SECRET!,
    linearApiBaseUrl: process.env.LINEAR_API_BASE_URL,
    linearApiToken: process.env.LINEAR_API_TOKEN,
  };

  try {
    const result = await handle(payload, config);
    res.json({ success: true, messageIds: result.discordMessageIds });
  } catch (err) {
    console.error('Connector error:', err);
    res.status(500).json({ error: err.message });
  }
});
```

## Assumptions

- The Linear webhook payload includes the issue ID and an initial comment cursor or comment list (per plan).
- The Discord bot has the `Send Messages` permission in the target channel (channel ID = Linear issue ID).
- Comments are retrieved using Linear's cursor-based pagination endpoint for issue comments (`GET /issues/{id}/comments`).
- The integration aggregates all comment bodies into one message, respecting Discord's 2000-character limit by splitting into multiple messages.
- The `Linear-Signature` header verification is performed by the webhook receiver before calling `handle`; this connector only checks `webhookTimestamp` freshness.
- Linear API returns comments in the shape `{ data: Comment[], nextCursor: string | null }`.
- Discord API returns `{ id: string }` on successful message creation.

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://linear.app/developers/webhooks
// Source: https://discord.com/developers/docs/resources/channel#create-message

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "action": "update",
  "type": "Issue",
  "data": {
    "id": "issue-uuid",
    "state": {
      "type": "canceled"
    }
  },
  "createdAt": "2024-01-01T12:00:00.000Z",
  "webhookTimestamp": 1704110400000
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://discord.com/api/v9/channels/{channelId}/messages",
    "response": {
      "id": "message-id",
      "channelId": "channel-id",
      "content": "Digest of comments..."
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface LinearWebhookPayload {
  action: 'update';
  type: 'Issue';
  data: {
    id: string;
    state: {
      type: string;
    };
  };
  createdAt: string;
  webhookTimestamp: number;
  comments?: LinearComment[];
  cursor?: string;
}

export interface LinearComment {
  id: string;
  body: string;
  createdAt: string;
  user: {
    id: string;
    name: string;
  };
}

export interface ConnectorConfig {
  discordBotToken: string;
  linearWebhookSecret: string;
  linearApiBaseUrl?: string;
  linearApiToken?: string;
  fetch?: typeof fetch;
  linearFetch?: typeof fetch;
}

export interface HandleResult {
  discordMessageIds: string[];
  commentsFetched: number;
}

async function fetchAllComments(
  issueId: string,
  initialCursor: string | undefined,
  config: ConnectorConfig
): Promise<LinearComment[]> {
  const baseUrl = config.linearApiBaseUrl ?? 'https://api.linear.app';
  const fetchFn = config.linearFetch ?? config.fetch ?? fetch;
  const allComments: LinearComment[] = [];
  let cursor = initialCursor;

  do {
    const url = new URL(`${baseUrl}/issues/${issueId}/comments`);
    if (cursor) {
      url.searchParams.set('cursor', cursor);
    }

    const headers: Record<string, string> = {
      Accept: 'application/json',
    };
    if (config.linearApiToken) {
      headers.Authorization = `Bearer ${config.linearApiToken}`;
    }

    const response = await fetchFn(url.toString(), {
      method: 'GET',
      headers,
    });

    if (!response.ok) {
      throw new Error(`Linear API error: ${response.status} ${response.statusText} for GET ${url.toString()}`);
    }

    const data = (await response.json()) as {
      data: LinearComment[];
      nextCursor: string | null;
    };

    allComments.push(...data.data);
    cursor = data.nextCursor ?? undefined;
  } while (cursor);

  return allComments;
}

function formatDigest(issueId: string, comments: LinearComment[]): string {
  if (comments.length === 0) {
    return `Digest of comments for Linear issue ${issueId}:\n\nNo comments found.`;
  }

  const lines = comments.map((c, i) => `- Comment ${i + 1}: ${c.body}`);
  return `Digest of comments for Linear issue ${issueId}:\n\n${lines.join('\n')}`;
}

function splitMessage(content: string, maxLength = 2000): string[] {
  if (content.length <= maxLength) {
    return [content];
  }

  const chunks: string[] = [];
  let remaining = content;

  while (remaining.length > 0) {
    if (remaining.length <= maxLength) {
      chunks.push(remaining);
      break;
    }

    let splitIndex = remaining.lastIndexOf('\n', maxLength);
    if (splitIndex === -1 || splitIndex < maxLength * 0.5) {
      splitIndex = maxLength;
    }

    chunks.push(remaining.slice(0, splitIndex));
    remaining = remaining.slice(splitIndex).trimStart();
  }

  return chunks;
}

async function postToDiscord(channelId: string, content: string, config: ConnectorConfig): Promise<string> {
  const fetchFn = config.fetch ?? fetch;
  const url = `https://discord.com/api/v9/channels/${channelId}/messages`;

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bot ${config.discordBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  });

  if (!response.ok) {
    throw new Error(`Discord API error: ${response.status} ${response.statusText} for POST ${url}`);
  }

  const data = (await response.json()) as { id: string };
  return data.id;
}

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!config.discordBotToken) {
    throw new Error('Missing required config: discordBotToken');
  }
  if (!config.linearWebhookSecret) {
    throw new Error('Missing required config: linearWebhookSecret');
  }

  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: must be an object');
  }
  if (payload.action !== 'update') {
    throw new Error(`Invalid payload action: expected 'update', got '${payload.action}'`);
  }
  if (payload.type !== 'Issue') {
    throw new Error(`Invalid payload type: expected 'Issue', got '${payload.type}'`);
  }
  if (!payload.data || !payload.data.id) {
    throw new Error('Missing required field: data.id (issueId)');
  }
  if (!payload.data.state || !payload.data.state.type) {
    throw new Error('Missing required field: data.state.type');
  }
  const stateType = payload.data.state.type;
  if (stateType !== 'done' && stateType !== 'canceled') {
    throw new Error(`Issue not closed: state.type is '${stateType}', expected 'done' or 'canceled'`);
  }
  if (typeof payload.webhookTimestamp !== 'number') {
    throw new Error('Missing required field: webhookTimestamp');
  }

  const now = Date.now();
  const timestampDiff = Math.abs(now - payload.webhookTimestamp);
  if (timestampDiff > 60_000) {
    throw new Error(`Webhook timestamp too old or future: ${payload.webhookTimestamp} (diff: ${timestampDiff}ms)`);
  }

  const issueId = payload.data.id;
  const channelId = issueId;

  let comments: LinearComment[];
  if (payload.comments && payload.comments.length > 0) {
    comments = payload.comments;
  } else {
    comments = await fetchAllComments(issueId, payload.cursor, config);
  }

  const digest = formatDigest(issueId, comments);
  const chunks = splitMessage(digest);

  const messageIds: string[] = [];
  for (const chunk of chunks) {
    const messageId = await postToDiscord(channelId, chunk, config);
    messageIds.push(messageId);
  }

  return {
    discordMessageIds: messageIds,
    commentsFetched: comments.length,
  };
}

