  linearApiToken?: string;
  fetch?: typeof fetch;
  linearFetch?: typeof fetch;
}

export interface HandleResult {
  discordMessageIds: string[];
  commentsFetched: number;
}

async function fetchAllComments(
  issueId: string,
  initialCursor: string | undefined,
  config: ConnectorConfig
): Promise<LinearComment[]> {
  const baseUrl = config.linearApiBaseUrl ?? 'https://api.linear.app';
  const fetchFn = config.linearFetch ?? config.fetch ?? fetch;
  const allComments: LinearComment[] = [];
  let cursor = initialCursor;

  do {
    const url = new URL(`${baseUrl}/issues/${issueId}/comments`);
    if (cursor) {
      url.searchParams.set('cursor', cursor);
    }

    const headers: Record<string, string> = {
      Accept: 'application/json',
    };
    if (config.linearApiToken) {
      headers.Authorization = `Bearer ${config.linearApiToken}`;
    }

    const response = await fetchFn(url.toString(), {
      method: 'GET',
      headers,
    });

    if (!response.ok) {
      throw new Error(`Linear API error: ${response.status} ${response.statusText} for GET ${url.toString()}`);
    }

    const data = (await response.json()) as {
      data: LinearComment[];
      nextCursor: string | null;
    };

    allComments.push(...data.data);
    cursor = data.nextCursor ?? undefined;
  } while (cursor);

  return allComments;
}

function formatDigest(issueId: string, comments: LinearComment[]): string {
  if (comments.length === 0) {
    return `Digest of comments for Linear issue ${issueId}:\n\nNo comments found.`;
  }

  const lines = comments.map((c, i) => `- Comment ${i + 1}: ${c.body}`);
  return `Digest of comments for Linear issue ${issueId}:\n\n${lines.join('\n')}`;
}

function splitMessage(content: string, maxLength = 2000): string[] {
  if (content.length <= maxLength) {
    return [content];
  }

  const chunks: string[] = [];
  let remaining = content;

  while (remaining.length > 0) {
    if (remaining.length <= maxLength) {
      chunks.push(remaining);
      break;
    }

    let splitIndex = remaining.lastIndexOf('\n', maxLength);
    if (splitIndex === -1 || splitIndex < maxLength * 0.5) {
      splitIndex = maxLength;
    }

    chunks.push(remaining.slice(0, splitIndex));
    remaining = remaining.slice(splitIndex).trimStart();
  }

  return chunks;
}

async function postToDiscord(channelId: string, content: string, config: ConnectorConfig): Promise<string> {
  const fetchFn = config.fetch ?? fetch;
  const url = `https://discord.com/api/v9/channels/${channelId}/messages`;

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bot ${config.discordBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  });

  if (!response.ok) {
    throw new Error(`Discord API error: ${response.status} ${response.statusText} for POST ${url}`);
  }

  const data = (await response.json()) as { id: string };
  return data.id;
}

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!config.discordBotToken) {
    throw new Error('Missing required config: discordBotToken');
  }
  if (!config.linearWebhookSecret) {
    throw new Error('Missing required config: linearWebhookSecret');
  }

  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: must be an object');
  }
  if (payload.action !== 'update') {
    throw new Error(`Invalid payload action: expected 'update', got '${payload.action}'`);
  }
  if (payload.type !== 'Issue') {
    throw new Error(`Invalid payload type: expected 'Issue', got '${payload.type}'`);
  }
  if (!payload.data || !payload.data.id) {
    throw new Error('Missing required field: data.id (issueId)');
  }
  if (!payload.data.state || !payload.data.state.type) {
    throw new Error('Missing required field: data.state.type');
  }
  const stateType = payload.data.state.type;
  if (stateType !== 'done' && stateType !== 'canceled') {
    throw new Error(`Issue not closed: state.type is '${stateType}', expected 'done' or 'canceled'`);
  }
  if (typeof payload.webhookTimestamp !== 'number') {
    throw new Error('Missing required field: webhookTimestamp');
  }

  const now = Date.now();
  const timestampDiff = Math.abs(now - payload.webhookTimestamp);
  if (timestampDiff > 60_000) {
    throw new Error(`Webhook timestamp too old or future: ${payload.webhookTimestamp} (diff: ${timestampDiff}ms)`);
  }

  const issueId = payload.data.id;
  const channelId = issueId;

  let comments: LinearComment[];
  if (payload.comments && payload.comments.length > 0) {
    comments = payload.comments;
  } else {
    comments = await fetchAllComments(issueId, payload.cursor, config);
  }

  const digest = formatDigest(issueId, comments);
  const chunks = splitMessage(digest);

  const messageIds: string[] = [];
  for (const chunk of chunks) {
    const messageId = await postToDiscord(channelId, chunk, config);
    messageIds.push(messageId);
  }

  return {
    discordMessageIds: messageIds,
    commentsFetched: comments.length,
  };
}

